# aplicar-v65-menu-contextual-customer-admin.ps1
# Corrige o menu conforme a tela:
#
# Em telas CUSTOMER (/dashboard, /events, /orders, etc):
# - mostra apenas menu customer
# - se o usuario for ADMIN/SUPER_ADMIN, aparece o botao "Entrar no admin"
#
# Em telas ADMIN (/admin/...):
# - mostra apenas menu admin/super admin
# - nao mostra Inicio/Criar evento/Meus ingressos/Suporte/Wallet duplicados
#
# Nao mexe na dashboard.

$ErrorActionPreference = "Stop"

$Root = Get-Location
$Stamp = Get-Date -Format "yyyyMMdd-HHmmss"

function Write-TextBase64File($RelativePath, $Base64Content) {
  $Target = Join-Path $Root $RelativePath
  $TargetDir = Split-Path $Target -Parent

  if (-not (Test-Path $TargetDir)) {
    New-Item -ItemType Directory -Path $TargetDir -Force | Out-Null
  }

  if (Test-Path $Target) {
    $Backup = "$Target.bak-v65-$Stamp"
    Copy-Item $Target $Backup -Force
    Write-Host "Backup criado: $Backup" -ForegroundColor DarkGray
  }

  $Content = [System.Text.Encoding]::UTF8.GetString([Convert]::FromBase64String($Base64Content))
  Set-Content -Path $Target -Value $Content -Encoding UTF8
  Write-Host "Atualizado: $RelativePath" -ForegroundColor Green
}

Write-Host "Aplicando v65 - menu contextual customer/admin..." -ForegroundColor Cyan

$HeaderBase64 = ""

Write-TextBase64File "apps\web\src\components\customer\CustomerHeader.tsx" $HeaderBase64

Write-Host ""
Write-Host "v65 aplicada com sucesso." -ForegroundColor Green
Write-Host ""
Write-Host "Como fica:" -ForegroundColor Cyan
Write-Host "- Em telas customer: menu customer + Entrar no admin." -ForegroundColor Cyan
Write-Host "- Em telas admin: menu admin/super admin apenas." -ForegroundColor Cyan
Write-Host ""
Write-Host "Agora reinicie o WEB:" -ForegroundColor Cyan
Write-Host 'cd "C:\Users\march\OneDrive\Área de Trabalho\plataforma-ingressos\apps\web"' -ForegroundColor Cyan
Write-Host "npm run dev" -ForegroundColor Cyan
